#!/usr/bin/env python3
"""Prepare reviewed Trip.com-only home Back changes from the pinned 1.1.0 source."""
from pathlib import Path,PurePosixPath
import base64,hashlib,json,shutil,lzma
ROOT=Path(__file__).resolve().parent
BASE=ROOT.parent/'homeback110'
PACKED=''
raw=base64.b64decode(PACKED,validate=True)
assert hashlib.sha256(raw).hexdigest()=='47e0f74075553f84aab1d17bd4ca8ee70978bc85e50a6256da2512bf544df724'
rows=json.loads(lzma.decompress(raw))
qa=(BASE/'QA_HomeBack_v1.1.0.json').read_bytes()
assert hashlib.sha256(qa).hexdigest()=='2274d239a6846d537641e896da9f43a89c8d05d63754e212e33d95c29ce4f9b9'
for name,digest in json.loads(qa)['sources'].items():
 assert hashlib.sha256((BASE/'src'/name).read_bytes()).hexdigest()==digest, 'Prior source changed: '+name
for part in ('src','publication'):
 assert not (ROOT/part).exists(), 'Use a clean checkout'
 shutil.copytree(BASE/part,ROOT/part)
shutil.copyfile(BASE/'README.md',ROOT/'README.md')
(ROOT/'publication/workflow.yml').unlink(missing_ok=True)
for name,row in rows.items():
 p=PurePosixPath(name)
 assert not p.is_absolute() and '..' not in p.parts and '\\' not in name
 target=ROOT/p;target.parent.mkdir(parents=True,exist_ok=True)
 if 'text' in row:
  assert not target.exists(), 'Unexpected prior file: '+name
  data=row['text'].encode()
 else:
  original=target.read_bytes()
  assert hashlib.sha256(original).hexdigest()==row['base_sha256'], 'Prior delta base changed: '+name
  lines=original.decode().splitlines(True)
  for start,end,replace in reversed(row['edits']):lines[start:end]=replace
  data=''.join(lines).encode()
 assert hashlib.sha256(data).hexdigest()==row['sha256'], 'Delta mismatch: '+name
 target.write_bytes(data)
print('PASS pinned source reconstruction:',len(rows),'changed/new files')
